import sys
import requests
import re
from urllib.parse import quote

def main():
    print("Package file: ", end="")
    package_file_path = input().strip()

    # Validate input path
    if not package_file_path or not package_file_path.strip():
        print("Invalid input path")
        sys.exit(1)

    # Validate and sanitize package names
    package_names = []
    try:
        with open(package_file_path, 'r', encoding='utf-8') as file:
            for line_num, line in enumerate(file, 1):
                line = line.strip()
                if not line:
                    continue
                # Validate package name: only allow alphanumeric, hyphens, underscores, dots
                if not re.match(r'^[a-zA-Z0-9._-]+$', line):
                    print(f"Invalid package name on line {line_num}: '{line}'")
                    continue
                package_names.append(line)
    except FileNotFoundError:
        print(f"Error: File '{package_file_path}' not found")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied when reading file '{package_file_path}'")
        sys.exit(1)

    if not package_names:
        print("No valid package names found")
        sys.exit(1)

    output_lines = []

    # Rate limiting: add a small delay between requests to avoid overwhelming the server
    import time
    delay = 0.5  # 500ms delay between requests

    for package_name in package_names:
        url = f"https://pypi.org/pypi/{quote(package_name)}/json"
        try:
            # Add a small delay to prevent rate flooding
            time.sleep(delay)

            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                try:
                    data = response.json()
                    # Validate that required field exists and version is a string
                    if 'info' in data and 'version' in data['info']:
                        version = data['info']['version']
                        # Validate version format (basic alphanumeric with dots and hyphens)
                        if re.match(r'^[0-9]+(\.[0-9]+(\.[0-9]+)?)?(\-[0-9]+)?$', version):
                            output_lines.append(f"{package_name}=={version}")
                        else:
                            output_lines.append(f"{package_name}: invalid version")
                    else:
                        output_lines.append(f"{package_name}: unavailable")
                except (KeyError, TypeError, ValueError) as e:
                    output_lines.append(f"{package_name}: unavailable")
            else:
                output_lines.append(f"{package_name}: unavailable")

        except requests.exceptions.Timeout:
            output_lines.append(f"{package_name}: unavailable")
        except requests.exceptions.ConnectionError:
            output_lines.append(f"{package_name}: unavailable")
        except requests.exceptions.RequestException as e:
            output_lines.append(f"{package_name}: unavailable")
        except Exception as e:
            output_lines.append(f"{package_name}: unavailable")

    # Print to stdout
    for line in output_lines:
        print(line)

    # Write to file with proper encoding
    try:
        with open('latest_versions.txt', 'w', encoding='utf-8') as file:
            for line in output_lines:
                file.write(line + '\n')
    except PermissionError:
        print(f"Error: Permission denied when writing to 'latest_versions.txt'")
        sys.exit(1)

if __name__ == "__main__":
    main()

