def parse_xml_with_entities(file_path, item_name):
    # Validate file path to prevent path traversal
    import os
    # Normalize and validate the path
    if not file_path or not isinstance(file_path, str):
        return "ERROR"

    # Ensure the path is absolute and within a safe directory
    # For security, we restrict to the current directory only
    if not file_path.startswith('/'):
        # If relative, ensure it's in the current directory
        if not file_path.startswith('./') and not file_path.startswith('../'):
            file_path = './' + file_path

    # Normalize path and check for traversal
    normalized_path = os.path.normpath(file_path)
    if '..' in normalized_path or '~' in normalized_path:
        return "ERROR"

    # Check if the path is within the current directory
    if not normalized_path.startswith('./'):
        return "ERROR"

    # Validate the file exists and is readable
    try:
        with open(normalized_path, 'r', encoding='utf-8') as file:
            content = file.read()
    except (OSError, IOError):
        return "ERROR"

    # Parse XML with entity resolution disabled for external entities
    # We use a custom parser that disables external entity resolution
    try:
        # Create a parser that does not resolve external entities
        parser = ET.XMLParser(encoding='utf-8', resolve_entities=False)
        root = ET.fromstring(content, parser=parser)
    except (ExpatError, ET.ParseError):
        return "ERROR"

    # Find the first item with the given name
    for item in root.findall('item'):
        if item.get('name') == item_name:
            value = item.get('value')
            if value is not None:
                # Since we disabled external entities, no entity resolution occurs
                # The value is already safe
                return value

    return "NOT_FOUND"

def main():
    try:
        file_path = sys.stdin.readline().strip()
        item_name = sys.stdin.readline().strip()

        if not file_path or not item_name:
