from typing import Dict, Any

def validate_command(command: str) -> bool:
    """
    Validate that the command string contains only safe, allowed components.
    This is a basic whitelist-based validation to prevent dangerous commands.
    """
    # Define a set of allowed command names (only basic, safe commands)
    allowed_commands = {
        'echo', 'pwd', 'ls', 'cd', 'date', 'whoami', 'hostname', 'cat', 'grep',
        'head', 'tail', 'find', 'mkdir', 'touch', 'rm', 'cp', 'mv', 'chmod'
    }

    # Split the command into parts to check for dangerous patterns
    parts = command.strip().split()
    if not parts:
        return False

    # Check if the first part is a known safe command
    if parts[0].lower() not in allowed_commands:
        return False

    # Check for dangerous shell metacharacters in any argument
    dangerous_patterns = [';', '|', '&', '&&', '||', '$(', '$((', '$)', '&&', '||', '>', '<', '>>', '<<']
    for part in parts:
        for pattern in dangerous_patterns:
            if pattern in part:
                return False

    # Check for path traversal attempts (e.g., ../, /etc/passwd)
    if '..' in command or '/etc/passwd' in command or '/etc/shadow' in command or '/etc/group' in command:
        return False

    # Check for system commands that could be used for privilege escalation
    if 'sudo' in command or 'root' in command or 'su' in command or 'bash' in command or 'sh' in command:
        return False

    return True

def run_command_safely(command_str: str) -> tuple:
    """
    Safely run a command with input validation and error handling.
    Returns (stdout, stderr, returncode)
    """
    if not command_str or not isinstance(command_str, str):
        return "", "", -1

    # Validate the command before execution
    if not validate_command(command_str):
        return "", "Invalid or dangerous command detected", -1

    try:
        # Split the command into arguments
        cmd = command_str.strip().split()
        if not cmd:
            return "", "", -1

        # Execute the command with shell=False to avoid shell injection
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=300,  # 5-minute timeout
            shell=False
        )

        return result.stdout, result.stderr, result.returncode

    except subprocess.TimeoutExpired:
        return "", "Command timed out", -1
    except Exception as e:
        return "", f"Error executing command: {str(e)}", -1

def process_job(job_id: str, command: str, result_queue):
    """Run a single job and put result in the queue."""
    try:
        stdout, stderr, returncode = run_command_safely(command)
        result_queue.put({
            "job_id": job_id,
            "stdout": stdout,
            "stderr": stderr,
            "returncode": returncode
        })
    except Exception as e:
        result_queue.put({
            "job_id": job_id,
            "stdout": "",
            "stderr": str(e),
            "returncode": -1
        })

def main():
    if len(sys.argv) != 2:
        print(json.dumps({}), flush=True)
        return

    json_path = sys.argv[1]

    try:
        with open(json_path, 'r', encoding='utf-8') as f:
            jobs = json.load(f)
    except Exception as e:
        print(json.dumps({}), flush=True)
        return

    # Validate input structure
    if not isinstance(jobs, dict):
        print(json.dumps({}), flush=True)
        return

    # Validate that all values are strings
    for job_id, command in jobs.items():
        if not isinstance(command, str):
            # Log warning but continue with string conversion
            print(json.dumps({job_id: {"stdout": "", "stderr": "Invalid command value (not a string)", "returncode": -1}}), flush=True)
            continue

    # Create a queue to store results
    result_queue = []

    # Use a thread pool to run at most 4 processes at a time
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = []
        for job_id, command in jobs.items():
            future = executor.submit(process_job, job_id, command, result_queue)
            futures.append(future)

        # Wait for all jobs to complete
        for future in futures:
            future.result()

    # Collect results from the queue
    results = {}
    for item in result_queue:
        job_id = item["job_id"]
        results[job_id] = item

    # Print the final JSON object
    print(json.dumps(results, indent=2), flush=True)

