        name = endpoint.get('name')
        url_text = endpoint.text.strip()

        if not url_text:
            continue

        # Validate URL format and protocol
        try:
            parsed_url = urlparse(url_text)
            if not parsed_url.scheme or parsed_url.scheme not in ['http', 'https']:
                print(f"{name}\tERROR")
                continue

            if not parsed_url.netloc:
                print(f"{name}\tERROR")
                continue

            # Validate that the URL does not contain dangerous protocols or file paths
            if parsed_url.scheme == 'file' or parsed_url.scheme == 'ftp' or parsed_url.scheme == 'data':
                print(f"{name}\tERROR")
                continue

            # Additional safety: prevent paths that could lead to local file access
            if parsed_url.path.startswith('/'):
                # Check for common dangerous patterns (e.g., file://, etc.)
                if any(part in parsed_url.path for part in ['../', 'etc/', '/etc/', '/proc/', '/var/']):
                    print(f"{name}\tERROR")
                    continue

            # Make the HTTP request with no redirects and 5-second timeout
            try:
                response = requests.get(url_text, allow_redirects=False, timeout=5)
