import html

def compute_fingerprint(data):
    return hashlib.md5(data).hexdigest().lower()

def escape_html(text):
    return html.escape(text, quote=True)

def main():
    paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            # Validate path: ensure it starts within a trusted directory (e.g., current directory)
            # Normalize path and check for traversal attempts
            if not line.startswith('/'):
                # Only accept relative paths that don't traverse up
                if '..' in line or '~' in line:
                    continue
            paths.append(line)

    if not paths:
        # If no paths provided, just print the template without rows
        try:
            with open('template.html', 'r', encoding='utf-8') as f:
                print(f.read())
        except FileNotFoundError:
            print("")  # Print empty string if template not found
        return

    # Read template with validation
    try:
        with open('template.html', 'r', encoding='utf-8') as f:
            template = f.read()
    except FileNotFoundError:
        print("")  # Print empty string if template not found
        return

    # Process each path safely
    rows = []
    for path in paths:
        # Validate path is within current directory (or a trusted subdirectory)
        try:
            # Normalize path and check if it's within the current directory
            abs_path = os.path.abspath(path)
            base_path = os.path.abspath('.')
            if not os.path.commonpath([abs_path, base_path]) == base_path:
                continue  # Path traversal detected
            if not os.path.isfile(abs_path):
                continue  # Not a file
            with open(abs_path, 'rb') as f:
                file_data = f.read()
            fingerprint = compute_fingerprint(file_data)
            escaped_path = escape_html(path)
            escaped_fingerprint = escape_html(fingerprint)
            row = f"<tr><td>{escaped_path}</td><td>{escaped_fingerprint}</td></tr>"
            rows.append(row)
        except (OSError, PermissionError, Exception):
            # In case of error reading file, use a placeholder
            escaped_path = escape_html(path)
            escaped_fingerprint = escape_html("ERROR")
            row = f"<tr><td>{escaped_path}</td><td>{escaped_fingerprint}</td></tr>"
            rows.append(row)

    # Replace {{rows}} in template with properly escaped rows
    # Ensure the placeholder is only replaced once and safely
    result = template.replace('{{rows}}', ''.join(rows))
    print(result)

