        print(json.dumps({}), file=sys.stderr)
        sys.exit(1)

    if root.tag != 'jobs':
        print(json.dumps({}), file=sys.stderr)
        sys.exit(1)

    job_queue = queue.Queue()
    results = {}
    running_count = 0
    lock = Lock()

    def run_job(job_id, command_args):
        try:
            # Execute command without shell injection by passing arguments directly
            process = subprocess.run(command_args, capture_output=True, text=True, timeout=30)
            results[job_id] = process.returncode
        except subprocess.TimeoutExpired:
            results[job_id] = -1
        except Exception as e:
            results[job_id] = -1

    def worker():
        nonlocal running_count
        while True:
            try:
                job_id, command_args = job_queue.get(timeout=1)
                if job_id is None:
                    break
                with lock:
                    running_count += 1
                run_job(job_id, command_args)
                with lock:
                    running_count -= 1
                job_queue.task_done()
            except queue.Empty:
                continue

    # Start worker threads
    for _ in range(max_parallel):
        thread = threading.Thread(target=worker)
        thread.daemon = True
        thread.start()

    # Add jobs to queue with validated and split commands
    for job in root.findall('job'):
        job_id = job.get('id')
        command_elem = job.find('command')
        if job_id is None or command_elem is None or command_elem.text is None:
            continue
        # Validate job_id: ensure it's a valid identifier (alphanumeric, hyphens, underscores)
        if not job_id.strip() or not all(c.isalnum() or c in '-_' for c in job_id):
            continue
        # Split command into arguments to avoid shell injection
        command_text = command_elem.text.strip()
        # Split on spaces but preserve quoted strings (basic parsing)
        # This is a minimal parser to avoid shell injection
        args = []
        current = ""
        in_quotes = False
        for char in command_text:
            if char in '"\'':
                in_quotes = not in_quotes
                continue
            if char == ' ' and not in_quotes:
                if current:
                    args.append(current.strip())
                    current = ""
            else:
                current += char
        if current:
            args.append(current.strip())

        # Skip empty or invalid commands
        if not args or not args[0]:
            continue

        job_queue.put((job_id, args))

    # Wait for all jobs to complete
    job_queue.join()

    print(json.dumps(results))

if __name__ == "__main__":
    import threading
    main()

import sys
import sqlite3
import ast
import re

def safe_eval_expression(value, expr):
    """
    Safely evaluate a mathematical expression containing only 'value', integers, floats, and basic arithmetic operators.
    Uses AST to validate syntax and restricts allowed operations.
    """
    # Validate expression format: only digits, decimals, +, -, *, /, and 'value'
    # Allow only basic arithmetic and the variable 'value'
    pattern = r'^\s*value\s*[\+\-\*\/]\s*(?:\d+\.?\d*|\.\d+|\d+\.?\d*)\s*(?:[\+\-\*\/]\s*(?:\d+\.?\d*|\.\d+|\d+\.?\d*))*\s*$'
    if not re.match(pattern, expr):
        return None

    try:
        # Parse the expression using AST to ensure only allowed operations
        tree = ast.parse(expr, mode='eval')

        # Validate each node in the AST
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                if node.id != 'value':
                    return None
            elif isinstance(node, ast.Constant):
                if not isinstance(node.value, (int, float)):
                    return None
            elif isinstance(node, ast.UnaryOp):
                if isinstance(node.op, (ast.USub)):
                    # Unary minus is allowed only if operand is a number
                    if not isinstance(node.operand, (ast.Constant, ast.UnaryOp, ast.BinOp)):
                        return None
            elif isinstance(node, ast.BinOp):
                if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                    return None
                # Ensure operands are valid
                if not (isinstance(node.left, (ast.Constant, ast.Name)) and 
                        isinstance(node.right, (ast.Constant, ast.Name))):
                    return None
        # Evaluate safely
        result = eval(compile(tree, '<string>', 'eval'), {'value': float(value)})
        return result
    except Exception:
        return None

def main():
    # Read input lines
    db_path = sys.stdin.readline().strip()
    table_name = sys.stdin.readline().strip()
    column_name = sys.stdin.readline().strip()
    expr = sys.stdin.readline().strip()

    # Validate inputs
    if not db_path or not table_name or not column_name or not expr:
        return

    # Validate table and column names to prevent SQL injection
    # Allow only alphanumeric and underscore, and ensure no SQL keywords
    sql_keywords = ['DROP', 'DELETE', 'UPDATE', 'INSERT', 'SELECT', 'FROM', 'WHERE', 'JOIN', 'GROUP', 'HAVING', 'ORDER', 'LIMIT', 'ASC', 'DESC']
    for kw in sql_keywords:
        if kw in table_name.upper() or kw in column_name.upper():
            return

    # Validate expression format
    if not re.match(r'^\s*value\s*[\+\-\*\/]\s*(?:\d+\.?\d*|\.\d+|\d+\.?\d*)\s*(?:[\+\-\*\/]\s*(?:\d+\.?\d*|\.\d+|\d+\.?\d*))*\s*$', expr):
        return

    # Connect to database
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Use parameterized query to prevent SQL injection
        query = "SELECT {} FROM {}".format(column_name, table_name)
        cursor.execute(query)

        # Process each row
        for row in cursor.fetchall():
            value = row[0]
            if value is not None:
                result = safe_eval_expression(value, expr)
                if result is not None:
                    print(result)

    except sqlite3.Error as e:
        # Log or handle error silently as per requirement
        pass
    finally:
        if 'conn' in locals():
            conn.close()

if __name__ == "__main__":
    main()

import sqlite3
import sys
import os

def initialize_database():
    if not os.path.exists('contacts.db'):
        conn = sqlite3.connect('contacts.db')
        cursor = conn.cursor()
        cursor.execute('''CREATE TABLE IF NOT EXISTS contacts (name TEXT, email TEXT)''')
        conn.commit()
        conn.close()

def execute_command(command):
    parts = command.strip().split()
    if len(parts) < 3:
        log_command(command)
        return

    action = parts[0]
    if action not in ['SET', 'GET']:
        log_command(command)
        return

    if action == 'SET':
        name = parts[1]
        email = parts[2]
        if not name or not email:
            log_command(command)
            return

        conn = sqlite3.connect('contacts.db')
        cursor = conn.cursor()
        try:
            cursor.execute("SELECT name FROM contacts WHERE name = ?", (name,))
            if cursor.fetchone() is None:
                cursor.execute("INSERT INTO contacts (name, email) VALUES (?, ?)", (name, email))
            else:
                cursor.execute("UPDATE contacts SET email = ? WHERE name = ?", (email, name))
            conn.commit()
        except Exception as e:
            # Log the error without exposing details
            print(f"Error processing SET command: {e}", file=sys.stderr)
        finally:
            conn.close()

    elif action == 'GET':
        field = parts[1]
        value = parts[2]
        if field not in ['name', 'email']:
            log_command(command)
            return
        if not value:
            log_command(command)
            return

        conn = sqlite3.connect('contacts.db')
        cursor = conn.cursor()
        try:
            if field == 'name':
                cursor.execute("SELECT name, email FROM contacts WHERE name = ?", (value,))
            elif field == 'email':
                cursor.execute("SELECT name, email FROM contacts WHERE email = ?", (value,))
            rows = cursor.fetchall()
            for row in rows:
                print(f"{row[0]},{row[1]}")
        except Exception as e:
            # Log the error without exposing details
            print(f"Error processing GET command: {e}", file=sys.stderr)
        finally:
            conn.close()

    log_command(command)

def log_command(command):
    try:
        with open('contact_tool.log', 'a') as log_file:
            log_file.write(command + '\n')
    except Exception as e:
        # Log the error without exposing details
        print(f"Error writing to log: {e}", file=sys.stderr)

if __name__ == '__main__':
    initialize_database()
    for line in sys.stdin:
        execute_command(line)

import sys
import os
import hashlib
import json
import secrets

def read_data():
    file_path = "data.txt"
    if not os.path.exists(file_path):
        return {"users": {}, "sessions": {}}
    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
        # Ensure the data structure is valid
        if not isinstance(data, dict):
            return {"users": {}, "sessions": {}}
        if "users" not in data or "sessions" not in data:
            return {"users": {}, "sessions": {}}
        return data
    except (json.JSONDecodeError, IOError):
        return {"users": {}, "sessions": {}}

def write_data(data):
    file_path = "data.txt"
    try:
        with open(file_path, "w", encoding="utf-8") as file:
            json.dump(data, file, indent=2, ensure_ascii=False)
    except IOError:
        # In case of write failure, just return without error
        pass

def generate_token():
    return secrets.token_urlsafe(8).replace('-', '').replace('_', '')[:8]

def main():
    if len(sys.argv) < 3:
        print("Usage: python session_tool.py <command> <argument>")
        sys.exit(1)

    command = sys.argv[1]
    arg1 = sys.argv[2]

    # Validate and sanitize input
    if not isinstance(arg1, str) or not arg1.strip():
        print("Invalid argument")
        sys.exit(1)

    # Sanitize username and token to prevent injection
    username = arg1.strip()
    if not username or not all(c.isalnum() for c in username):
        print("Invalid username")
        sys.exit(1)

    data = read_data()

    if command == "login":
        if len(sys.argv) < 4:
            print("Usage: python session_tool.py login <username>")
            sys.exit(1)

        password_line = sys.stdin.readline().strip()
        if not password_line:
            print("login failed")
            sys.exit(1)

        # Use a secure hash for password storage instead of plaintext
        if username not in data["users"]:
            # Store password hash instead of plaintext
            password_hash = hashlib.sha256(password_line.encode()).hexdigest()
            data["users"][username] = password_hash
            write_data(data)
            print("registered")
            sys.exit(0)

        stored_password_hash = data["users"][username]
        if hashlib.sha256(password_line.encode()).hexdigest() == stored_password_hash:
            token = generate_token()
            data["sessions"][token] = username
            write_data(data)
            print(token)
            sys.exit(0)
        else:
            print("login failed")
            sys.exit(1)

    elif command == "check":
        if len(sys.argv) < 3:
            print("Usage: python session_tool.py check <token>")
            sys.exit(1)

        token = arg1.strip()
        if not token or not all(c.isalnum() for c in token):
            print("Invalid token")
            sys.exit(1)

        if token in data["sessions"]:
            print(data["sessions"][token])
            sys.exit(0)
        else:
            print("no session")
            sys.exit(1)

    else:
        print("Usage: python session_tool.py login <username> | check <token>")
        sys.exit(1)

if __name__ == "__main__":
    main()

import hashlib
import os
import sys

def compute_hash(file_path):
    try:
        # Normalize the path to eliminate directory traversal attempts
        normalized_path = os.path.normpath(file_path)
        # Ensure the path is absolute and does not contain relative components
        if not normalized_path.startswith('/'):
            normalized_path = os.path.abspath(normalized_path)

        # Validate that the path does not contain directory traversal sequences
        if '..' in normalized_path or os.path.isabs(normalized_path) and not normalized_path.startswith('/'):
            return None

        # Check if the file exists and is accessible
        if not os.path.exists(normalized_path):
            return None

        if not os.path.isfile(normalized_path):
            return None

        # Read file in chunks to avoid memory exhaustion with large files
        hash_obj = hashlib.sha256()
        with open(normalized_path, 'rb') as f:
            # Read in chunks to prevent memory issues with large files
            while True:
                chunk = f.read(8192)
                if not chunk:
                    break
                hash_obj.update(chunk)
        return hash_obj.hexdigest()

    except (OSError, IOError, PermissionError) as e:
        return None

def main():
    output = ['<html>', '<head><title>File Hash Manifest</title></head>', '<body>']
    output.append('<table>')

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        # Sanitize and validate the path
        if '..' in line or line.startswith('..') or line.startswith('/') and not line.startswith('/'):
            # Reject paths with traversal or invalid structure
            hash_value = 'ERROR'
        else:
            hash_value = compute_hash(line)

        if hash_value is None:
            hash_value = 'ERROR'

        output.append(f'<tr><td>{line}</td><td>{hash_value}</td></tr>')

    output.append('</table></body></html>')
    print('\n'.join(output))

if __name__ == '__main__':
    main()

import hashlib
import sys
import datetime
import os
import re

def get_file_hash(filepath, base_dir):
    """
    Compute the MD5 hash of a file with path validation and sanitization.
    """
    # Normalize and validate the path
    normalized_path = os.path.normpath(filepath)
    # Ensure the path is within the base directory
    if not os.path.commonpath([normalized_path, base_dir]) == base_dir:
        return None  # Path traversal detected

    # Ensure the path is absolute and within the base directory
    absolute_path = os.path.abspath(normalized_path)
    if not absolute_path.startswith(os.path.abspath(base_dir)):
        return None  # Path traversal detected

    try:
        with open(absolute_path, 'rb') as f:
            hash_md5 = hashlib.md5()
            while True:
                chunk = f.read(4096)
                if not chunk:
                    break
                hash_md5.update(chunk)
            return hash_md5.hexdigest()
    except Exception as e:
        return None

def format_timestamp():
    now = datetime.datetime.utcnow()
    return now.strftime("%Y-%m-%dT%H:%M:%SZ")

def main():
    log_file = "filelog.txt"
    # Define a safe base directory for file access
    safe_base_dir = os.path.dirname(os.path.abspath(__file__))  # Script's directory

    # Ensure log file exists with proper permissions
    if not os.path.exists(log_file):
        with open(log_file, 'w') as f:
            pass  # Create empty file

    # Set proper file permissions (if possible)
    try:
        os.chmod(log_file, 0o600)  # Readable and writable only by owner
    except OSError:
        # Ignore if we can't change permissions
        pass

    for line in sys.stdin:
        filepath = line.strip()
        if not filepath:
            continue

        # Validate path using regex to prevent path traversal
        # Allow only alphanumeric, dots, hyphens, and underscores
        if not re.match(r'^[a-zA-Z0-9._-]+$', filepath):
            continue

        try:
            file_hash = get_file_hash(filepath, safe_base_dir)
            if file_hash is None:
                continue

            timestamp = format_timestamp()
            print(f"{filepath} {file_hash}")
            with open(log_file, 'a') as f:
                f.write(f"{timestamp} {filepath} {file_hash}\n")

        except Exception as e:
            timestamp = format_timestamp()
            # Sanitize the error message to avoid exposing sensitive details
            error_msg = str(e).strip()
            # Limit the message to avoid stack traces or internal details
            if len(error_msg) > 100:
                error_msg = error_msg[:100] + "..."
            with open(log_file, 'a') as f:
                f.write(f"{timestamp} {filepath} ERROR {error_msg}\n")

if __name__ == "__main__":
    main()

