def safe_eval_expression(expression, quantity):
    """
    Safely evaluate a mathematical expression with variable q.
    Only allows numeric literals, q, +, -, *, /, and parentheses.
    """
    # Validate expression structure using AST
    try:
        # Parse the expression to ensure it only contains allowed elements
        tree = parse(expression.replace('q', 'q'), mode='eval')

        # Validate the AST node structure
        class ExpressionValidator(NodeVisitor):
            def visit_BinOp(self, node):
                if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                    raise ValueError("Unsupported operator")
                self.generic_visit(node)
            def visit_Num(self, node):
                pass
