                raise ValueError("Boolean operations not allowed")
            def visit_Starred(self, node):
                raise ValueError("Starred expressions not allowed")
            def visit_ExceptHandler(self, node):
                raise ValueError("Exception handling not allowed")
            def visit_With(self, node):
                raise ValueError("With statement not allowed")
            def visit_AnnAssign(self, node):
                raise ValueError("Annotation assignment not allowed")
            def visit_Assign(self, node):
                raise ValueError("Assignment not allowed")
            def visit_AugAssign(self, node):
                raise ValueError("Augmented assignment not allowed")
            def visit_Return(self, node):
                raise ValueError("Return statement not allowed")
            def visit_If(self, node):
                raise ValueError("If statement not allowed")
            def visit_For(self, node):
                raise ValueError("For loop not allowed")
            def visit_While(self, node):
                raise ValueError("While loop not allowed")
            def visit_FunctionDef(self, node):
                raise ValueError("Function definition not allowed")
            def visit_ClassDef(self, node):
                raise ValueError("Class definition not allowed")
            def visit_With(self, node):
                raise ValueError("With statement not allowed")
            def visit_Dict(self, node):
                raise ValueError("Dictionary not allowed")
            def visit_Set(self, node):
                raise ValueError("Set not allowed")
            def visit_List(self, node):
                raise ValueError("List not allowed")
            def visit_Tuple(self, node):
                raise ValueError("Tuple not allowed")
            def visit_Starred(self, node):
                raise ValueError("Starred expression not allowed")

        validator = ExpressionValidator()
        validator.visit(tree)

        # Replace q with quantity in a safe way
        # We already validated the structure, so we can evaluate safely
        expr_with_q = expression.replace('q', str(quantity))

        # Evaluate the expression using safe literal evaluation
        # Since we've validated the AST, we can now safely evaluate
        result = eval(expr_with_q, {"__builtins__": {}}, {})

        # Ensure result is a number
        if isinstance(result, (int, float)):
            if result == int(result):
                return str(int(result))
            else:
                return f"{result:.1f}"
        else:
