import sys
import sqlite3
import requests
import xml.etree.ElementTree as ET
from datetime import datetime
from urllib.parse import urlparse
import re

def is_valid_date(date_str):
    """Validate if the date string is in ISO 8601 format (YYYY-MM-DD)"""
    if not date_str or not isinstance(date_str, str):
        return False
    pattern = r'^\d{4}-\d{2}-\d{2}$'
    if not re.match(pattern, date_str):
        return False
    try:
        datetime.strptime(date_str, '%Y-%m-%d')
        return True
    except ValueError:
        return False

def is_valid_url(url):
    """Validate if the URL is well-formed and comes from an allowed domain"""
    if not url or not isinstance(url, str):
        return False
    try:
        parsed = urlparse(url)
        if not parsed.scheme or not parsed.netloc:
            return False
        # Allow only specific domains (example: example.com, api.example.com)
        allowed_domains = ['example.com', 'api.example.com']
        domain = parsed.netloc.lower()
        return any(domain.endswith(allowed_domain) for allowed_domain in allowed_domains)
    except Exception:
        return False

def main():
    if len(sys.argv) != 2:
        print("Usage: python sync_users.py <date>")
        sys.exit(1)

    date_arg = sys.argv[1]

    # Validate date input
    if not is_valid_date(date_arg):
        print("Error: Invalid date format. Use YYYY-MM-DD.")
        sys.exit(1)

    # Parse XML configuration
    try:
        tree = ET.parse('sync.xml')
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML configuration: {e}")
        sys.exit(1)
    except FileNotFoundError:
        print("Error: sync.xml file not found")
        sys.exit(1)

    # Extract database file, query, and endpoint with validation
    try:
        db_file = root.find('database').get('file')
        if not db_file or not isinstance(db_file, str):
            print("Error: Missing or invalid database file path in configuration")
            sys.exit(1)

        query_text = root.find('query').text
        if not query_text or not isinstance(query_text, str):
            print("Error: Missing or invalid query in configuration")
            sys.exit(1)

        endpoint_url = root.find('endpoint').get('url')
        if not endpoint_url or not isinstance(endpoint_url, str):
            print("Error: Missing or invalid endpoint URL in configuration")
            sys.exit(1)

        # Validate endpoint URL
        if not is_valid_url(endpoint_url):
            print("Error: Endpoint URL is not from an allowed domain")
            sys.exit(1)

