import sys
import json
import sqlite3
import requests
import re
import ast
from urllib.parse import urlparse

def safe_eval_expression(expr):
    """
    Safely evaluate arithmetic expressions with only integers, +, -, *, /, and parentheses.
    Uses AST to validate and evaluate expressions without executing arbitrary code.
    """
    try:
        # Parse the expression using AST to ensure only safe operations are used
        tree = ast.parse(expr, mode='eval')

        # Validate the AST node
        if not isinstance(tree.body, (ast.Num, ast.UnaryOp, ast.BinOp, ast.Constant)):
            raise ValueError("Invalid expression: contains unsupported operations")

        # Check for dangerous operations (e.g., imports, function calls, etc.)
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                if node.id in ('__import__', 'open', 'exec', 'eval', 'compile', 'os', 'sys'):
                    raise ValueError("Invalid expression: contains dangerous function call")
            if isinstance(node, ast.Call):
                raise ValueError("Invalid expression: contains function call")
            if isinstance(node, ast.Attribute):
                raise ValueError("Invalid expression: contains attribute access")
            if isinstance(node, ast.Compare):
                raise ValueError("Invalid expression: contains comparison operations")
            if isinstance(node, ast.BoolOp):
                raise ValueError("Invalid expression: contains boolean operations")

        # Evaluate the expression safely
        result = eval(compile(tree, '<string>', 'eval'), {"__builtins__": {}}, {})

        # Ensure result is a number and convert to integer
        if isinstance(result, float):
            # Check for division by zero or floating point results
            if result != int(result):
                raise ValueError("Invalid expression: result is not a whole number")
            return int(result)
        elif isinstance(result, int):
            return result
        else:
            raise ValueError("Invalid expression: result is not a number")

    except Exception as e:
        raise ValueError(f"Invalid expression: {expr} - {str(e)}")

def parse_query(query):
    """
    Replace {{...}} placeholders with evaluated expressions using safe evaluation.
    Returns the modified query string.
    """
    def replace_match(match):
        expr = match.group(1)
        try:
            result = safe_eval_expression(expr)
            return str(result)
        except Exception as e:
            raise ValueError(f"Error evaluating expression {expr}: {e}")

    # Find all {{...}} patterns and replace with evaluated expressions
    pattern = r'\{\{([^}]+)\}\}'
    try:
        result = re.sub(pattern, replace_match, query)
        return result
    except Exception as e:
        raise ValueError(f"Error parsing query: {e}")

def validate_url(url):
    """
    Validate that the URL is well-formed and has a valid scheme.
    """
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except Exception:
        return False

def run_check(check):
    name = check["name"]
    db_path = check["db"]
    query = check["query"]
    threshold = check["threshold"]
    webhook = check["webhook"]

    # Validate input fields
    if not isinstance(name, str) or not name.strip():
        raise ValueError("Invalid check name")
    if not isinstance(db_path, str) or not db_path.strip():
        raise ValueError("Invalid database path")
    if not isinstance(query, str) or not query.strip():
        raise ValueError("Invalid query")
    if not isinstance(threshold, (int, float)) or threshold < 0:
        raise ValueError("Invalid threshold value")
    if not isinstance(webhook, str) or not webhook.strip():
        raise ValueError("Invalid webhook URL")

    # Validate webhook URL
    if not validate_url(webhook):
        raise ValueError("Invalid webhook URL format")

    # Parse and replace placeholders in query
    try:
        parsed_query = parse_query(query)
    except Exception as e:
        print(f"{name} 0 failed")
        return f"{name} 0 failed"

    # Validate the resulting SQL query (basic structure check)
    # We assume the query is valid SQL, but we do not allow arbitrary SQL injection
    # by ensuring that only numbers are inserted via expressions
    try:
        # Connect to database and execute query
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(parsed_query)
        result = cursor.fetchone()
        if result is None:
            value = 0
        else:
            value = int(result[0])
        conn.close()
    except sqlite3.Error as e:
        print(f"{name} 0 failed")
        return f"{name} 0 failed"
    except Exception as e:
        print(f"{name} 0 failed")
        return f"{name} 0 failed"

    # Determine outcome
    if value > threshold:
        try:
            response = requests.post(
                webhook,
                json={"check": name, "value": value},
                headers={"Content-Type": "application/json"},
                timeout=10  # Prevent hanging requests
            )
            if response.status_code < 400:
                outcome = "sent"
            else:
                outcome = "failed"
        except requests.exceptions.RequestException as e:
            outcome = "failed"
    else:
        outcome = "skipped"

    return f"{name} {value} {outcome}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python alertcheck.py checks.json")
        sys.exit(1)

