import sys
import json
import requests
from xml.etree import ElementTree as ET
from urllib.parse import urlparse
from typing import Dict, List, Optional

def is_valid_url(url: str) -> bool:
    """Validate URL format to prevent open redirects and SSRF."""
    try:
        result = urlparse(url)
        return all([result.scheme in ['http', 'https'], result.netloc])
    except Exception:
        return False

def parse_rss_xml(xml_content: str) -> Optional[tuple[str, str]]:
    """Parse RSS 2.0 XML content safely, with XXE prevention."""
    try:
        # Disable external entities to prevent XXE attacks
        parser = ET.XMLParser(encoding='utf-8', resolve_entities=False)
        root = ET.fromstring(xml_content, parser=parser)

        # Look for <item> elements
        items = root.findall('.//item')
        if not items:
            return None, None

        first_item = items[0]
        title_elem = first_item.find('title')
        link_elem = first_item.find('link')

        if title_elem is not None and link_elem is not None:
            title = title_elem.text.strip() if title_elem.text else ""
            link = link_elem.get('href') or ""
            return title, link

        return None, None
    except ET.ParseError:
        return None, None
    except Exception:
        return None, None

def main():
    if len(sys.argv) != 2:
        print(json.dumps({"feeds": []}))
        return

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(json.dumps({"feeds": []}))
        return

    if "feeds" not in config or not isinstance(config["feeds"], list):
        print(json.dumps({"feeds": []}))
        return

    result_feeds: List[Dict[str, str]] = []

    for feed in config["feeds"]:
        if not isinstance(feed, dict) or "name" not in feed or "url" not in feed:
            result_feeds.append({"name": feed.get("name", ""), "error": "failed"})
            continue

        name = feed["name"]
        url = feed.get("url", "")

        # Validate URL before making request
        if not is_valid_url(url):
            result_feeds.append({"name": name, "error": "failed"})
            continue

        try:
            # Add headers to prevent some common attacks (e.g., malformed requests)
            response = requests.get(
                url,
                timeout=10,
                headers={"User-Agent": "FeedDigest/1.0"},
                allow_redirects=False
            )

            if response.status_code != 200:
                result_feeds.append({"name": name, "error": "failed"})
                continue

            content = response.text

            # Strictly validate RSS 2.0 XML content
            if not content.startswith('<?xml') or 'rss' not in content.lower():
                result_feeds.append({"name": name, "error": "failed"})
                continue

            # Parse XML safely
            title, link = parse_rss_xml(content)

            if title and link:
                result_feeds.append({
                    "name": name,
                    "title": title,
                    "link": link
                })
            else:
                result_feeds.append({
                    "name": name,
                    "error": "failed"
                })

        except requests.exceptions.RequestException as e:
            # Log specific request errors without exposing details
            result_feeds.append({"name": name, "error": "failed"})
        except Exception:
            # Catch any unexpected parsing or processing errors
            result_feeds.append({"name": name, "error": "failed"})

    print(json.dumps({"feeds": result_feeds}))

