import sys
import urllib.request
import xml.etree.ElementTree as ET
import re
import ast
from typing import Optional

def validate_and_parse_threshold(threshold_str: str) -> float:
    """
    Safely parse and evaluate a mathematical expression using AST to prevent code injection.
    Only allows numbers, +, -, *, /, and parentheses.
    """
    # Remove spaces
    expression = threshold_str.strip().replace(" ", "")

    # Validate expression structure using AST
    try:
        # Parse the expression to ensure it's a valid arithmetic expression
        # Only allow numbers, +, -, *, /, and parentheses
        tree = ast.parse(expression, mode='eval')

        # Validate that the expression contains only allowed nodes
        for node in ast.walk(tree):
            if isinstance(node, (ast.Num, ast.Constant)):
                continue
            elif isinstance(node, ast.UnaryOp):
                if not isinstance(node.op, (ast.USub)):
                    raise ValueError("Invalid operator")
            elif isinstance(node, ast.BinOp):
                if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                    raise ValueError("Invalid operator")
            elif isinstance(node, ast.Compare):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Call):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Name):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Str):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Attribute):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Subscript):
                raise ValueError("Invalid expression")

        # Evaluate the expression safely
        result = eval(compile(tree, f"<string>", "eval"), {"__builtins__": {}}, {})
        return float(result)

    except (SyntaxError, ValueError, TypeError) as e:
        raise ValueError(f"Invalid expression: {expression}")

def parse_config(config_path: str) -> tuple[Optional[str], Optional[str]]:
    """
    Parse configuration file with strict validation.
    Only accepts 'feed_url' and 'threshold' keys.
    Values must be non-empty and properly formatted.
    """
    feed_url = None
    threshold = None

    with open(config_path, 'r', encoding='utf-8') as file:
        for line in file:
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            if '=' not in line:
                continue

            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()

            if key == 'feed_url':
                if not value:
                    continue
                # Validate feed_url format: must start with http(s)://
                if not (value.startswith('http://') or value.startswith('https://')):
                    raise ValueError(f"Invalid feed_url format: {value}")
                feed_url = value
            elif key == 'threshold':
                if not value:
                    continue
                # Validate threshold value contains only numbers, +, -, *, /, and parentheses
                if not re.match(r'^[0-9]+(\.[0-9]+)?(\s*[+\-*/()]\s*[0-9]+(\.[0-9]+)?)*$', value):
                    raise ValueError(f"Invalid threshold format: {value}")
                threshold = value
            else:
                # Unknown key
                continue

    return feed_url, threshold

def extract_price_sum(xml_content: str) -> float:
    """
    Extract all price elements from XML content and sum their values.
    Only processes text content of elements with tag 'price'.
    """
    try:
        root = ET.fromstring(xml_content)
        prices = []
        for elem in root.iter():
            if elem.tag == 'price' and elem.text is not None:
                price_str = elem.text.strip()
                if price_str:
                    price = float(price_str)
                    prices.append(price)
        return sum(prices)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML format: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_stock.py <config_file_path>")
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        feed_url, threshold_str = parse_config(config_path)

        if not feed_url:
            print("Error: feed_url is missing in configuration file")
            sys.exit(1)

        if not threshold_str:
            print("Error: threshold is missing in configuration file")
            sys.exit(1)

        # Fetch XML content from feed_url
        try:
            with urllib.request.urlopen(feed_url) as response:
                xml_content = response.read().decode('utf-8')
        except Exception as e:
            print(f"Error fetching feed URL: {e}")
            sys.exit(1)

        # Extract sum of prices
        try:
            price_sum = extract_price_sum(xml_content)
            threshold_value = validate_and_parse_threshold(threshold_str)

            if price_sum > threshold_value:
                print("OK")
            else:
                print("LOW")

        except Exception as e:
            print(f"Error processing data: {e}")
            sys.exit(1)

    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
